CREATE TABLE assessments (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, passing_score INT NOT NULL DEFAULT 60, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE assessment_questions (id UUID PRIMARY KEY, assessment_id UUID NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, question_text VARCHAR(3000) NOT NULL, question_type VARCHAR(20) NOT NULL DEFAULT 'SINGLE_CHOICE', points INT NOT NULL DEFAULT 1, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE question_options (id UUID PRIMARY KEY, question_id UUID NOT NULL REFERENCES assessment_questions(id) ON DELETE CASCADE, option_text VARCHAR(2000) NOT NULL, correct BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE assessment_attempts (id UUID PRIMARY KEY, assessment_id UUID NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, score INT NOT NULL, passed BOOLEAN NOT NULL, submitted_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_assessments_course ON assessments(course_id); CREATE INDEX idx_attempts_user ON assessment_attempts(user_id);